css:
header {
  background-color:  #12343b;
  text-align: center;
  padding: 40px;
  color: #e8f8ff;
}


button {
  padding: 12px 18px;
  border: none;
  background-color: #ffb703;
  color: black;
  font-size: 16px;
  cursor: pointer;
  border-radius: 8px;
}

button:hover {
  background-color: #fb8500;
}

main {
  max-width: 1000px;
  margin: 0 auto;
  padding: 30px;
}

section {
  background-color: white;
  margin-bottom: 30px;
  padding: 25px;
  border-radius: 16px;
}

h2 {
  color: #0077b6;
}

.products {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-bottom: 20px;
}

.cards {
  width: 220px;
}

.card {
  background-color: #caf0f8;
  padding: 20px;
  border-radius: 14px;
  transition: 0.3s;
}

.card h3 {
  margin-top: 0;
}

.description {
  min-height: 70px;
}

.rooms{
  display: inline-block;
  margin-top: 10px;
  font-weight: bold;
  color: #023047;
}

.activeCard {
  background-color: #90e0ef;
  transform: scale(1.05);
}

.infoText {
  font-size: 20px;
  margin-top: 20px;
  color: #023047;
}

.ticketForm {
  display: flex;
  flex-direction: column;
  gap: 15px;
  max-width: 350px;
}

input {
  display: block;
  width: 100%;
  margin-top: 5px;
  padding: 10px;
  font-size: 16px;
}

.resultText {
  font-size: 20px;
  font-weight: bold;
  color: #0077b6;
}

.footer {
  text-align: center;
  padding: 20px;
  background-color: #023047;
  color: white;
}
